function detectSubjectKey(subjectStr) {
  if (!subjectStr) return 'general';
  const str = subjectStr.toString().toLowerCase();

  if (str.includes('คณิต')) return 'math';
  if (str.includes('ฟิสิกส์')) return 'physics';
  if (str.includes('เคมี')) return 'chemistry';
  if (str.includes('ชีวะ')) return 'biology';
  if (str.includes('วิทย์')) return 'science';
  if (str.includes('อังกฤษ') || str.includes('eng')) return 'english';
  if (str.includes('ไทย')) return 'thai';
  if (str.includes('สังคม') || str.includes('ประวัติ')) return 'social';
  if (str.includes('จีน')) return 'chinese';

  return 'general';
}

function getCurrentlySelectedPresetTexts(category, prefix) {
  const p = prefix ? `${prefix}_` : '';
  const selectedTexts = new Set();

  for (let i = 1; i <= 6; i++) {
    const input = document.getElementById(`${p}${category}_${i}`);
    if (input && input.value) {
      const val = input.value.trim();
      if (val) selectedTexts.add(val);
    }
  }
  return selectedTexts;
}

function getSubjectPresetOptionsHtml(category, itemIndex, prefix, chosenSubjKey) {
  const p = prefix ? `${prefix}_` : '';
  const detected = detectSubjectKey(document.getElementById(prefix ? 'admin_eval_subject' : 'eval_subject')?.value);
  const subjKey = chosenSubjKey && chosenSubjKey !== 'auto' ? chosenSubjKey : detected;

  const genData = SUBJECT_EVALUATION_PRESETS.general[category];
  const specData = (subjKey !== 'general' && SUBJECT_EVALUATION_PRESETS[subjKey]) ? SUBJECT_EVALUATION_PRESETS[subjKey][category] : null;

  const usedTexts = getCurrentlySelectedPresetTexts(category, prefix);
  const currentInputVal = document.getElementById(`${p}${category}_${itemIndex}`)?.value?.trim() || '';

  let html = `<option value="">-- เลือกคำแนะนำสำเร็จรูป (ข้อที่ ${itemIndex}) --</option>`;

  const renderGroup = (label, listAdvanced, listInter, listFound) => {
    let groupHtml = '';
    
    if (listAdvanced && listAdvanced.length > 0) {
      listAdvanced.forEach((item, idx) => {
        if (!usedTexts.has(item.text) || item.text === currentInputVal) {
          groupHtml += `<option value="${escapeHtmlAttr(item.text)}">[เก่ง ${idx+1}] ${escapeHtmlText(item.label)} (${item.text.length} อักษร)</option>`;
        }
      });
    }

    if (listInter && listInter.length > 0) {
      listInter.forEach((item, idx) => {
        if (!usedTexts.has(item.text) || item.text === currentInputVal) {
          groupHtml += `<option value="${escapeHtmlAttr(item.text)}">[กลาง ${idx+1}] ${escapeHtmlText(item.label)} (${item.text.length} อักษร)</option>`;
        }
      });
    }

    if (listFound && listFound.length > 0) {
      listFound.forEach((item, idx) => {
        if (!usedTexts.has(item.text) || item.text === currentInputVal) {
          groupHtml += `<option value="${escapeHtmlAttr(item.text)}">[อ่อน ${idx+1}] ${escapeHtmlText(item.label)} (${item.text.length} อักษร)</option>`;
        }
      });
    }

    if (groupHtml) {
      return `<optgroup label="${label}">${groupHtml}</optgroup>`;
    }
    return '';
  };

  if (specData) {
    const specNameMap = {
      math: 'คณิตศาสตร์', physics: 'ฟิสิกส์', chemistry: 'เคมี', biology: 'ชีววิทยา',
      science: 'วิทยาศาสตร์', english: 'ภาษาอังกฤษ', thai: 'ภาษาไทย', social: 'สังคมศึกษา', chinese: 'ภาษาจีน'
    };
    html += renderGroup(`🎯 ข้อความเฉพาะวิชา ${specNameMap[subjKey] || subjKey}`, specData.advanced, specData.intermediate, specData.foundation);
  }

  if (genData) {
    html += renderGroup(`⭐ ข้อความทั่วไป (ทุกวิชา)`, genData.advanced, genData.intermediate, genData.foundation);
  }

  if (itemIndex === 6) {
    html += `<option value="CUSTOM" selected>✍️ พิมพ์ระบุเอง (ข้อสุดท้ายสำหรับกรอกข้อมูลเพิ่มเติมตามต้องการ)</option>`;
  } else {
    html += `<option value="CUSTOM">✍️ พิมพ์ระบุเอง (Custom Text)...</option>`;
  }

  return html;
}

function escapeHtmlAttr(str) {
  return (str || '').replace(/"/g, '&quot;');
}

function escapeHtmlText(str) {
  return (str || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function refreshPresetDropdownsForCategory(category, prefix, chosenSubjKey) {
  const p = prefix ? `${prefix}_` : '';
  for (let i = 1; i <= 6; i++) {
    const select = document.getElementById(`${p}${category}_${i}_select`);
    const input = document.getElementById(`${p}${category}_${i}`);
    if (select) {
      const curSelectVal = select.value;
      select.innerHTML = getSubjectPresetOptionsHtml(category, i, prefix, chosenSubjKey);
      if (curSelectVal && Array.from(select.options).some(o => o.value === curSelectVal)) {
        select.value = curSelectVal;
      }
    }
    if (input) {
      updateCharCountBadge(input, `${p}${category}_${i}_count`);
    }
  }
}

function onSubjectFilterChange(category, prefix, selectElem) {
  const subjKey = selectElem.value;
  refreshPresetDropdownsForCategory(category, prefix, subjKey);
}

function applyFeedbackPreset(selectElem, targetInputId) {
  const input = document.getElementById(targetInputId);
  if (!input) return;

  const val = selectElem.value;
  if (val === 'CUSTOM') {
    input.focus();
  } else if (val) {
    input.value = val;
  }
  updateCharCountBadge(input, targetInputId + '_count');

  let category = 'strength';
  let prefix = '';

  if (targetInputId.startsWith('admin_eval_')) {
    prefix = 'admin_eval';
    const parts = targetInputId.replace('admin_eval_', '').split('_');
    category = parts[0];
  } else {
    const parts = targetInputId.replace('eval_', '').split('_');
    category = parts[0];
  }

  if (category) {
    refreshPresetDropdownsForCategory(category, prefix);
  }
}

function updateCharCountBadge(inputElem, countBadgeId) {
  const badge = document.getElementById(countBadgeId);
  if (!badge || !inputElem) return;

  const len = (inputElem.value || '').trim().length;
  badge.textContent = `${len}/60 ตัวอักษร`;

  if (len >= 60) {
    badge.style.color = '#10b981';
    badge.style.fontWeight = '700';
  } else if (len > 0) {
    badge.style.color = '#f59e0b';
    badge.style.fontWeight = '600';
  } else {
    badge.style.color = '#94a3b8';
    badge.style.fontWeight = '500';
  }

  // Refresh sibling dropdowns when typing custom text to auto-hide matched presets
  const inputId = inputElem.id;
  let category = '';
  let prefix = '';

  if (inputId.startsWith('admin_eval_')) {
    prefix = 'admin_eval';
    category = inputId.replace('admin_eval_', '').split('_')[0];
  } else if (inputId.startsWith('eval_')) {
    category = inputId.replace('eval_', '').split('_')[0];
  }

  if (category) {
    refreshPresetDropdownsForCategory(category, prefix);
  }
}

function quickFillFeedbackSection(category, level, prefix) {
  const p = prefix ? `${prefix}_` : '';
  const subjKey = detectSubjectKey(document.getElementById(prefix ? 'admin_eval_subject' : 'eval_subject')?.value);
  
  let specItems = (subjKey !== 'general' && SUBJECT_EVALUATION_PRESETS[subjKey]) ? SUBJECT_EVALUATION_PRESETS[subjKey][category]?.[level] : null;
  let genItems = SUBJECT_EVALUATION_PRESETS.general[category]?.[level] || [];

  let pool = [];
  if (specItems) pool = pool.concat(specItems);
  pool = pool.concat(genItems);

  let filled = 0;
  for (let i = 1; i <= 4; i++) {
    const input = document.getElementById(`${p}${category}_${i}`);
    const select = document.getElementById(`${p}${category}_${i}_select`);
    if (input && pool[filled]) {
      input.value = pool[filled].text;
      if (select) select.value = pool[filled].text;
      updateCharCountBadge(input, `${p}${category}_${i}_count`);
      filled++;
    }
  }

  refreshPresetDropdownsForCategory(category, prefix, subjKey);
  const levelTh = level === 'advanced' ? 'เด็กเก่ง' : level === 'intermediate' ? 'เด็กกลาง' : 'เด็กต้องพัฒนา';
  showToast(`เติมชุดคำแนะนำวิชาสำหรับ "${levelTh}" เรียบร้อยแล้ว (4 ข้อ)`, 'info');
}

function clearFeedbackSection(category, prefix) {
  const p = prefix ? `${prefix}_` : '';
  for (let i = 1; i <= 6; i++) {
    const input = document.getElementById(`${p}${category}_${i}`);
    const select = document.getElementById(`${p}${category}_${i}_select`);
    if (input) {
      input.value = '';
      if (select) select.value = '';
      updateCharCountBadge(input, `${p}${category}_${i}_count`);
    }
  }
  refreshPresetDropdownsForCategory(category, prefix);
}

function populateAllEvaluationPresetDropdowns() {
  ['strength', 'improvement', 'recommendation'].forEach(cat => {
    refreshPresetDropdownsForCategory(cat, '');
    refreshPresetDropdownsForCategory(cat, 'admin_eval');
  });
}

document.addEventListener('DOMContentLoaded', () => {
  setTimeout(populateAllEvaluationPresetDropdowns, 500);
});